import ElementWrapper from '../../ElementWrapper.jsx';
import { ElementPropTypes } from '@/lib/prop-types.js';
import useMapElement from '@/lib/design/use-map-element.jsx';
import PropTypes from 'prop-types';

const MapKenya = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapKenyaContent element={element} />
    </ElementWrapper>
  );
};

export const MapKenyaPresent = ({ element }) => {
  return <MapKenyaContent element={element} />;
};

export const MapKenyaPreview = () => {
  return <MapKenyaContent element={{ config: { data: [], fill: '#f9fafb', stroke: '#f9fafb' } }} />;
};

